```tsx
// routes/discussion.tsx
export const clientLoader =
  (ctrl: Controller) =>
  async ({ params }: LoaderFunctionArgs) => {
    const id = params.discussionId as string;
    return Promise.all([
      ctrl.fetchIfStale(DiscussionResource.get, { id }),
      ctrl.fetchIfStale(CommentResource.getList, { discussionId: id }),
    ]);
  };

export default function DiscussionRoute() {
  const { discussionId } = useParams() as { discussionId: string };
  const discussion = useSuspense(DiscussionResource.get, { id: discussionId });
  return (
    <ContentLayout title={discussion.title}>
      <p>{discussion.body}</p>
      <RenameDiscussion id={discussionId} />
      <CommentsList discussionId={discussionId} />
    </ContentLayout>
  );
}

// features/comments/comments-list.tsx
export function CommentsList({ discussionId }: { discussionId: string }) {
  const ctrl = useController();
  const comments = useSuspense(CommentResource.getList, { discussionId });
  const sorted = useMemo(
    () => [...comments].sort((a, b) => b.createdAt - a.createdAt),
    [comments],
  );
  const addComment = async (body: string) => {
    await ctrl.fetch(CommentResource.create, { discussionId }, { body, discussionId });
    ctrl.expireAll(CommentResource.getList);
  };
  return (
    <>
      <CommentForm onSubmit={addComment} />
      <ul>{sorted.map((c) => <li key={c.id}>{c.body}</li>)}</ul>
    </>
  );
}

// features/discussions/rename-discussion.tsx
export function RenameDiscussion({ id }: { id: string }) {
  const ctrl = useController();
  return (
    <TitleForm
      onSubmit={(title) => ctrl.fetch(DiscussionResource.partialUpdate, { id }, { title })}
    />
  );
}
```

