Run a performance pass on our issues pages. We use @data-client/react 0.19 and @data-client/rest on React 19.2. No browser here, so skip live measurement. Write the changed files.

```ts
// resources.ts
export class User extends Entity {
  id = 0;
  name = '';
  static key = 'User';
}
export class Issue extends Entity {
  id = 0;
  title = '';
  author = { id: 0, name: '' };
  static key = 'Issue';
}
export const UserResource = resource({ path: '/users/:id', schema: User });
export const IssueResource = resource({ path: '/issues/:id', schema: Issue });
export const getIssueStats = new RestEndpoint({ path: '/issues/stats' });
export const getIssuePage = new RestEndpoint({
  path: '/issues',
  searchParams: {} as { page: number },
  schema: [Issue],
});
```

```tsx
// routes.tsx
export const issuesLoader = (ctrl: Controller) => () => ctrl.fetch(IssueResource.getList);

// rename-user.tsx
export function RenameUser({ id }: { id: number }) {
  const ctrl = useController();
  const rename = async (name: string) => {
    await ctrl.fetch(UserResource.partialUpdate, { id }, { name });
    ctrl.expireAll(IssueResource.getList);
  };
  return <NameForm onSubmit={rename} />;
}

// close-issue.tsx
export function DeleteIssue({ id }: { id: number }) {
  const ctrl = useController();
  const remove = async () => {
    await ctrl.fetch(IssueResource.delete, { id });
    ctrl.expireAll(getIssueStats);
    ctrl.expireAll(getIssuePage);
  };
  return <button onClick={remove}>Delete</button>;
}
```

