// issues-page.tsx
const IssueRow = memo(function IssueRow({ issue }: { issue: Issue }) {
  const ctrl = useController();
  return (
    <li>
      <TitleForm
        value={issue.title}
        onSubmit={(title) => ctrl.fetch(IssueResource.partialUpdate, { id: issue.id }, { title })}
      />
    </li>
  );
});

export function IssuesPage() {
  const issues = useSuspense(IssueResource.getList);
  const sorted = useMemo(() => [...issues].sort((a, b) => b.priority - a.priority), [issues]);
  return <ul>{sorted.map((issue) => <IssueRow key={issue.id} issue={issue} />)}</ul>;
}
